class Solution:
    def countUnivalSubtrees(self, root):
        if not root:
            return 0

        count = 0

        def dfs(node):
            nonlocal count
            # Returns True if subtree rooted at node is uni-value
            if not node:
                return True

            left_uni = dfs(node.left)
            right_uni = dfs(node.right)

            # Check if current node forms a uni-value subtree
            if left_uni and right_uni:
                if node.left and node.left.val != node.val:
                    return False
                if node.right and node.right.val != node.val:
                    return False
                count += 1
                return True

            return False

        dfs(root)
        return count

