class Solution:
    def singleNumber(self, nums: List[int]) -> List[int]:
        # Step 1: XOR all numbers
        xor_all = 0
        for num in nums:
            xor_all ^= num

        # Step 2: Find a set bit (rightmost set bit) - using bit manipulation
        diff_bit = xor_all & -xor_all

        # Step 3: Partition numbers into two groups and XOR each
        num1, num2 = 0, 0
        for num in nums:
            if num & diff_bit:
                num1 ^= num
            else:
                num2 ^= num

        return [num1, num2]

class Solution:
    def nthUglyNumber(self, n: int) -> int:
        ugly = [1] * n
        i2 = i3 = i5 = 0
        next2, next3, next5 = 2, 3, 5

        for i in range(1, n):
            next_ugly = min(next2, next3, next5)
            ugly[i] = next_ugly

            if next_ugly == next2:
                i2 += 1
                next2 = ugly[i2] * 2
            if next_ugly == next3:
                i3 += 1
                next3 = ugly[i3] * 3
            if next_ugly == next5:
                i5 += 1
                next5 = ugly[i5] * 5

        return ugly[-1]

