class Solution:
    def minCostII(self, costs: List[List[int]]) -> int:
        if not costs:
            return 0

        n = len(costs)
        k = len(costs[0])

        # Use the first row directly as the initial DP state
        dp_prev = costs[0][:]

        for i in range(1, n):
            # Find the two smallest values and their indices in dp_prev
            # Initialize with large values
            min1 = float('inf')
            min2 = float('inf')
            min1_idx = -1

            # Single pass to find smallest and second smallest
            for j in range(k):
                val = dp_prev[j]
                if val < min1:
                    min2 = min1
                    min1 = val
                    min1_idx = j
                elif val < min2:
                    min2 = val

            # Build current DP row
            # Use list comprehension for speed and clarity
            dp_curr = [
                costs[i][j] + (min2 if j == min1_idx else min1)
                for j in range(k)
            ]

            dp_prev = dp_curr

        return min(dp_prev)

class Solution:
    def missingNumber(self, nums: List[int]) -> int:
        n = len(nums)
        expected_sum = n * (n + 1) // 2
        actual_sum = sum(nums)
        return expected_sum - actual_sum

