class Solution:
    def alienOrder(self, words):
        # Step 1: Initialize graph with only unique characters
        # Use dict comprehension for faster initialization
        in_degree = {c: 0 for word in words for c in word}
        adj = defaultdict(set)

        # Step 2: Build graph - optimize by avoiding repeated min() calls
        for i in range(len(words) - 1):
            w1, w2 = words[i], words[i+1]
            # Early prefix check - use direct comparison
            if len(w1) > len(w2) and w1.startswith(w2):
                return ""

            # Find first differing character
            for c1, c2 in zip(w1, w2):
                if c1 != c2:
                    if c2 not in adj[c1]:
                        adj[c1].add(c2)
                        in_degree[c2] += 1
                    break

        # Step 3: Topological sort - optimize queue initialization
        q = deque([c for c, deg in in_degree.items() if deg == 0])
        result = []

        # Use local variable references for speed
        adj_local = adj
        in_deg_local = in_degree
        append = result.append
        popleft = q.popleft

        while q:
            c = popleft()
            append(c)
            for neighbor in adj_local[c]:
                in_deg_local[neighbor] -= 1
                if in_deg_local[neighbor] == 0:
                    q.append(neighbor)

        # Cycle detection
        if len(result) != len(in_degree):
            return ""

        return "".join(result)

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

    @staticmethod
    def fromList(lst):
        if not lst:
            return None
        root = TreeNode(lst[0])
        queue = [root]
        i = 1
        # Use index-based queue traversal to avoid O(n) pop(0) overhead
        head = 0
        while head < len(queue) and i < len(lst):
            node = queue[head]
            head += 1
            if i < len(lst) and lst[i] is not None:
                node.left = TreeNode(lst[i])
                queue.append(node.left)
            i += 1
            if i < len(lst) and lst[i] is not None:
                node.right = TreeNode(lst[i])
                queue.append(node.right)
            i += 1
        return root

class Solution:
    def closestValue(self, root: TreeNode, target: float) -> int:
        closest = root.val
        node = root
        while node:
            # Compute difference once to avoid repeated abs() calls
            diff = node.val - target
            if diff < 0:
                diff = -diff
            closest_diff = closest - target
            if closest_diff < 0:
                closest_diff = -closest_diff

            if diff < closest_diff or (diff == closest_diff and node.val < closest):
                closest = node.val

            # Binary search direction
            if target < node.val:
                node = node.left
            else:
                node = node.right
        return closest

