class Solution:
    def removeInvalidParentheses(self, s: str) -> List[str]:
        # Precompute counts of '(' and ')' to remove for minimal removals
        left_rem = 0
        right_rem = 0
        for ch in s:
            if ch == '(':
                left_rem += 1
            elif ch == ')':
                if left_rem > 0:
                    left_rem -= 1
                else:
                    right_rem += 1

        result = []
        n = len(s)

        # Use a set to avoid duplicates directly during backtracking
        seen = set()

        def backtrack(idx, left_count, right_count, left_rem, right_rem, expr):
            # Pruning: if we've processed all characters
            if idx == n:
                if left_rem == 0 and right_rem == 0 and left_count == right_count:
                    candidate = ''.join(expr)
                    if candidate not in seen:
                        seen.add(candidate)
                        result.append(candidate)
                return

            ch = s[idx]

            # Option 1: Remove current character if it's a parenthesis and we still need removals
            if ch == '(' and left_rem > 0:
                backtrack(idx + 1, left_count, right_count, left_rem - 1, right_rem, expr)
            elif ch == ')' and right_rem > 0:
                backtrack(idx + 1, left_count, right_count, left_rem, right_rem - 1, expr)

            # Option 2: Keep current character
            expr.append(ch)
            if ch == '(':
                backtrack(idx + 1, left_count + 1, right_count, left_rem, right_rem, expr)
            elif ch == ')':
                if right_count < left_count:  # only keep ')' if it doesn't make prefix invalid
                    backtrack(idx + 1, left_count, right_count + 1, left_rem, right_rem, expr)
            else:  # letters
                backtrack(idx + 1, left_count, right_count, left_rem, right_rem, expr)
            expr.pop()

        backtrack(0, 0, 0, left_rem, right_rem, [])

        return result

