class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

    @staticmethod
    def from_list(values):
        if not values:
            return None
        root = TreeNode(values[0])
        queue = deque([root])
        i = 1
        while queue and i < len(values):
            node = queue.popleft()
            if values[i] is not None:
                node.left = TreeNode(values[i])
                queue.append(node.left)
            i += 1
            if i < len(values) and values[i] is not None:
                node.right = TreeNode(values[i])
                queue.append(node.right)
            i += 1
        return root

class Solution:
    def verticalOrder(self, root: TreeNode):
        if not root:
            return []

        # BFS to get min and max column
        queue = deque([(root, 0)])
        min_col = 0
        max_col = 0

        while queue:
            node, col = queue.popleft()
            if col < min_col:
                min_col = col
            elif col > max_col:
                max_col = col

            if node.left:
                queue.append((node.left, col - 1))
            if node.right:
                queue.append((node.right, col + 1))

        # Now we know the range, allocate result list directly
        width = max_col - min_col + 1
        result = [[] for _ in range(width)]
        offset = -min_col

        # Second BFS to fill the result
        queue = deque([(root, 0)])
        while queue:
            node, col = queue.popleft()
            result[col + offset].append(node.val)

            if node.left:
                queue.append((node.left, col - 1))
            if node.right:
                queue.append((node.right, col + 1))

        return result
